import {canonical,hash,distributionOK} from '../shared.mjs';
export function buildRequest(observation,allowed,config={model:'fixture-v1',host:'offline'}) {
 if(!allowed.length||new Set(allowed).size!==allowed.length)throw Error('invalid allowed set');
 const question={type:'choice',instructions:'Choose the next encounter to reach charge 12 by round 12 while respecting the announced pressure target. Use only available public observations.',criteria:Object.fromEntries(allowed.map(k=>[k,k==='rest'?'Restore health and supplies without charge.':`Offer a ${k} encounter.`]))};
 const body={model:config.model,state:canonical(observation),questions:{encounter:question}};
 const binding={stateHash:hash(observation),questionHash:hash(question),episodeId:observation.episodeId,revision:observation.revision,allowed:[...allowed],model:config.model,host:config.host,adapterVersion:'beacon-adapter/1'};
