  const key=JSON.stringify([row.episodeId,row.revision]);if(seen.has(key))throw Error('duplicate observation identity');seen.add(key);
  if(episodeDomains.has(row.episodeId)&&episodeDomains.get(row.episodeId)!==row.domain)throw Error('episode spans incompatible domains');episodeDomains.set(row.episodeId,row.domain);
 }
 const domains={};
 for(const domain of [...new Set(rows.map(r=>r.domain))].sort()){
  const selected=rows.filter(r=>r.domain===domain);
  const bins=[{lo:0,hi:.5},{lo:.5,hi:.8},{lo:.8,hi:1.0000001}].map(bin=>{
   const xs=selected.filter(r=>r.score>=bin.lo&&r.score<bin.hi),groups=new Map();
   for(const row of xs){const g=groups.get(row.episodeId)||{yes:0,n:0};g.yes+=row.label;g.n++;groups.set(row.episodeId,g);}
   const rates=[...groups.values()].map(g=>g.yes/g.n),yes=xs.reduce((n,r)=>n+r.label,0),p=rates.length?rates.reduce((a,b)=>a+b,0)/rates.length:null;
   return {...bin,n:xs.length,yes,episodes:rates.length,p,rowRate:xs.length?yes/xs.length:null,interval:episodeInterval(rates)};
  });
  domains[domain]={episodes:new Set(selected.map(r=>r.episodeId)).size,rows:selected.length,bins};
 }
 return {version:2,event:'next round alive and inside target',estimand:'equal-episode mean event rate within the named domain and score bin',intervalMethod:'Hoeffding bound across independent episode summaries; alpha=0.05',domain:Object.keys(domains),domains};
}
export function brier(rows,predict){
 if(!rows.length)throw Error('empty evaluation');
 return rows.reduce((sum,row)=>{const p=predict(row);if(!Number.isFinite(p)||p<0||p>1||![0,1].includes(row.label))throw Error('invalid forecast or label');return sum+(p-row.label)**2;},0)/rows.length;
}
export function select(proposal,table,domain,threshold=.65){
 if(!proposal.ok)return {use:false,reason:proposal.error};
