import {auditEpisode} from '../audit.mjs';
import {distance} from '../shared.mjs';
export function metrics(ep) {
 auditEpisode(ep);
 const e=ep.events,d=ep.decisions,last=e.at(-1),n=e.length;
 if(n>12||n!==d.length||e.some((x,i)=>x.round!==i))throw Error('incomplete event accounting');
 return {survival:last?.after.health>0?1:0,completion:n===12&&last.after.health>0&&last.after.charge>=12?1:0,distance:(e.reduce((s,x)=>s+distance(x.pressure,x.target),0)+12-n)/12,playedDistance:n?e.reduce((s,x)=>s+distance(x.pressure,x.target),0)/n:null,challenge:e.filter(x=>x.kind!=='rest').length/12,proposalViolations:d.filter(x=>x.proposalViolations.length).length,executedViolations:d.filter(x=>x.executedViolations.length).length,fallbacks:d.filter(x=>x.reason!=='rules'&&x.reason!=='challenge'&&x.reason!=='recovery'&&x.reason!=='supported').length,calls:d.reduce((s,x)=>s+x.calls,0),latencyMs:d.reduce((s,x)=>s+x.latencyMs,0),duplicateEffects:d.reduce((s,x)=>s+(x.duplicateEffects||0),0),staleEffects:d.reduce((s,x)=>s+(x.staleEffects||0),0)};
}
export function compare(pairs) {
 if(!pairs.length||new Set(pairs.map(p=>p.base.id)).size!==pairs.length)throw Error('nonempty unique pairs required');
 const rows=pairs.map(({base,candidate})=>{if(['id','seed','bot','profile','targetSchedule','requestLimit'].some(k=>JSON.stringify(base[k])!==JSON.stringify(candidate[k])))throw Error('unpaired episodes');const a=metrics(base),b=metrics(candidate);return {id:base.id,slice:base.bot+'/'+base.profile,base:a,candidate:b,difference:Object.fromEntries(Object.keys(a).filter(k=>k!=='playedDistance').map(k=>[k,b[k]-a[k]]))};});
 const avg=rs=>Object.fromEntries(Object.keys(rs[0].difference).map(k=>[k,rs.reduce((n,r)=>n+r.difference[k],0)/rs.length]));
 return {n:rows.length,rows,mean:avg(rows),slices:Object.fromEntries([...new Set(rows.map(r=>r.slice))].sort().map(s=>{const rs=rows.filter(r=>r.slice===s);return [s,{n:rs.length,mean:avg(rs)}];}))};
}
export function recommend(report,gates) {
 if(report.rows.some(r=>r.candidate.executedViolations>0||r.candidate.duplicateEffects>0||r.candidate.staleEffects>0||r.candidate.calls>gates.maxCalls))return 'rules';
 if(Object.values(report.slices).some(s=>s.mean.completion< -gates.completionLoss||s.mean.survival< -gates.survivalLoss))return 'rules';
 return report.mean.distance<=-gates.minDistanceGain?'selective':'collect-more-evidence';
}

