export function reserve(s,context,now) {
 if(s.pending)return {state:s,error:'in-flight'};if(s.used>=s.maxRequests)return {state:s,error:'budget-exhausted'};
 const pending={token:s.serial+1,episodeId:context.episodeId,revision:context.revision,deadline:now+s.timeoutMs};
 return {state:{...s,used:s.used+1,serial:pending.token,pending},ticket:pending};
}
export function settle(s,ticket,current,now,result) {
 if(!s.pending||s.pending.token!==ticket.token)return {state:s,accepted:false,error:'stale'};
 if(ticket.episodeId!==current.episodeId||ticket.revision!==current.revision)return {state:{...s,pending:null},accepted:false,error:'stale'};
 const state={...s,pending:null};if(now>=ticket.deadline)return {state,accepted:false,error:'timeout'};
 if(!result.ok)return {state,accepted:false,error:result.error};return {state,accepted:true,proposal:result};
}
export function expire(s,now) {return s.pending&&now>=s.pending.deadline?{...s,pending:null}:s;}
